// src/pages/Home.js
import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Bar, Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  PointElement,
  LineElement,
} from "chart.js";

// Register ChartJS components
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  PointElement,
  LineElement
);

export default function Home() {
  const [status, setStatus] = useState("");
  const [predictionHistory, setPredictionHistory] = useState([]);

  useEffect(() => {
    const API_URL = process.env.REACT_APP_API_URL;

    fetch(`${API_URL}/`) // backend root
      .then(res => res.text())
      .then(data => setStatus(data))
      .catch(() => setStatus("Backend not reachable"));

    const stored = JSON.parse(localStorage.getItem("predictionHistory") || "[]");
    setPredictionHistory(stored);
  }, []);

  // Prepare data for charts
  const clusterCounts = [0, 1, 2, 3].map(c =>
    predictionHistory.filter(p => p.result?.cluster === c).length
  );

  const monthlyActivity = [1, 2, 3, 4, 5, 6].map(i =>
    predictionHistory.filter((_, idx) => idx % 6 === i - 1).length
  );

  const clusterData = {
    labels: ["Cluster 0", "Cluster 1", "Cluster 2", "Cluster 3"],
    datasets: [
      {
        label: "Companies",
        data: clusterCounts,
        backgroundColor: "#3b82f6",
      },
    ],
  };

  const activityData = {
    labels: ["Jan", "Feb", "Mar", "Apr", "May", "Jun"],
    datasets: [
      {
        label: "Predictions",
        data: monthlyActivity,
        borderColor: "#10b981",
        backgroundColor: "#10b98133",
        fill: true,
        tension: 0.3,
      },
    ],
  };

  const kpis = [
    { title: "Total Predictions", value: predictionHistory.length },
    { title: "Avg Cluster", value: (predictionHistory.reduce((acc, p) => acc + (p.result?.cluster || 0), 0) / Math.max(predictionHistory.length, 1)).toFixed(2) },
    { title: "Successful Saves", value: predictionHistory.filter(p => p.result && !p.result.error).length },
    { title: "Backend Status", value: status },
  ];

  return (
    <div style={{ padding: "30px", maxWidth: "1200px", margin: "0 auto", fontFamily: "'Inter', Arial, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px", color: "#1e3c72" }}>Company Growth Analytics</h1>

      {/* KPI Cards */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: "20px", marginBottom: "30px" }}>
        {kpis.map((kpi, idx) => (
          <div key={idx} style={{
            background: "white",
            borderRadius: "12px",
            padding: "20px",
            boxShadow: "0 8px 20px rgba(0,0,0,0.05)",
            textAlign: "center",
            transition: "transform 0.2s ease",
          }}>
            <h4 style={{ marginBottom: "10px", color: "#1f2937" }}>{kpi.title}</h4>
            <p style={{ fontSize: "22px", fontWeight: "600", color: "#3b82f6" }}>{kpi.value}</p>
          </div>
        ))}
      </div>

      {/* Project Summary & Sections */}
      {[
        { title: "Project Summary", content: "The Company Growth Analytics project is designed to help businesses and analysts predict company growth trends based on multiple features such as industry, country, company age, and employee estimates. By combining a predictive model with an intuitive frontend interface, users can make data-driven decisions to support strategic planning and business development." },
        { title: "Problem Statement", content: "Many businesses struggle to forecast growth accurately due to scattered data, varying industry patterns, and lack of accessible predictive tools. Decision-making without proper analytics can lead to inefficient resource allocation and missed opportunities in competitive markets." },
        { title: "Mission", content: "Our mission is to provide a reliable, user-friendly tool that enables companies and analysts to understand growth patterns, predict potential outcomes, and make informed business decisions with confidence." },
        { title: "Why It Works", content: "The system works by using machine learning models trained on historical company data to identify growth patterns. Users interact with an intuitive interface that captures relevant company attributes, sends them to the backend for processing, and returns actionable predictions in real time. The combination of predictive modeling, data analytics, and simplicity ensures high usability and accurate insights." },
        { title: "Solution", content: "The solution is a web-based platform where users can input company features and instantly receive predictions about growth clusters, expected outcomes, and confidence levels. The platform integrates a Node.js backend to handle predictive logic and a React frontend for responsive, easy-to-use interaction, making data-driven decisions accessible to all users." },
      ].map((section, idx) => (
        <section key={idx} style={{ marginBottom: "25px", background: "#fff", padding: "20px", borderRadius: "12px", boxShadow: "0 8px 20px rgba(0,0,0,0.05)" }}>
          <h2 style={{ marginBottom: "15px", color: "#1e3c72" }}>{section.title}</h2>
          <p style={{ color: "#333", lineHeight: "1.6" }}>{section.content}</p>
        </section>
      ))}

      {/* Go to Predict Button */}
      <div style={{ textAlign: "center", marginTop: "20px" }}>
        <Link
          to="/predict"
          style={{
            padding: "15px 30px",
            backgroundColor: "#4CAF50",
            color: "white",
            fontWeight: "bold",
            textDecoration: "none",
            borderRadius: "8px",
            fontSize: "16px",
            transition: "0.3s",
          }}
        >
          Go to Predict Page
        </Link>
      </div>

      {/* Charts */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px", marginTop: "30px" }}>
        <div style={{ background: "#fff", padding: "20px", borderRadius: "12px", boxShadow: "0 8px 20px rgba(0,0,0,0.05)" }}>
          <h3 style={{ textAlign: "center", color: "#1e3c72" }}>Growth Cluster Distribution</h3>
          <Bar data={clusterData} options={{ responsive: true, plugins: { legend: { display: false } } }} />
        </div>

        <div style={{ background: "#fff", padding: "20px", borderRadius: "12px", boxShadow: "0 8px 20px rgba(0,0,0,0.05)" }}>
          <h3 style={{ textAlign: "center", color: "#1e3c72" }}>Prediction Activity</h3>
          <Line data={activityData} options={{ responsive: true, plugins: { legend: { display: false } } }} />
        </div>
      </div>

      {/* Backend status */}
      <section style={{ marginTop: "30px", textAlign: "center" }}>
        <p><strong>Backend status:</strong> {status}</p>
      </section>
    </div>
  );
}
